function fallback(el){el.onerror=null;el.style.display='none';el.parentElement.insertAdjacentHTML('afterbegin','<span style="font-size:30px">✦</span>')}
function iconNames(name){return name.replace(/^MAX /,'').split(' + ').map(s=>s.trim()).filter(s=>s&&!/^(Nincs|Teljesen|\d+\.|80\.|szint)/i.test(s))}
function item(name,result=false){const names=iconNames(name),icons=names.length?names.map(n=>'<img src="'+img(n)+'" alt="'+n+' ikon" title="'+n+'" onerror="fallback(this)">').join(''):'<span style="font-size:30px">—</span>';return '<div class="item '+(result?'result':'')+'"><div class="icons '+(names.length>1?'multi-icons':'')+'">'+icons+'</div><b>'+name+'</b></div>'}
function components(name){return name.replaceAll('MAX ','').split(' + ').map(s=>s.trim()).filter(Boolean)}
function componentUnlock(name,kind='any'){const clean=name.replace(/^MAX /,'').trim();if(kind==='weapon'&&weaponUnlocks[clean])return weaponUnlocks[clean];if(kind==='passive'&&passiveUnlocks[clean])return passiveUnlocks[clean];return weaponUnlocks[clean]||passiveUnlocks[clean]||characterUnlocks[clean]||'A hozzá tartozó kihívás vagy karakter feloldása után válik elérhetővé.'}
function unlockLines(name,kind='any'){return components(name).map(n=>'<span class="unlock-entry"><b>'+n+':</b> '+componentUnlock(n,kind)+'</span>').join('')}
function evolutionRule(r){if(r.passive==='Nincs passzív tárgy')return 'Fejleszd maximumra ezt a fegyvert: '+r.weapon+'. Ezután nyiss ki egy evolúcióra képes ládát; külön passzív tárgy nem kell.';const maxNote=r.passive.includes('MAX ')?' A MAX-szal jelölt tárgyakat is fejleszd maximumra.':'';return 'Fejleszd maximumra ezt a fegyvert: '+r.weapon+'. Legyen nálad ez a fejlesztő tárgy: '+r.passive.replaceAll('MAX ','')+'. Ezután nyiss ki egy evolúcióra képes ládát.'+maxNote}
function card(r){const done=localStorage.getItem('vs-'+r.id)==='1',search=(r.weapon+' '+r.passive+' '+r.result+' '+r.starter+' '+componentUnlock(r.weapon,'weapon')+' '+components(r.passive).map(x=>componentUnlock(x,'passive')).join(' ')).toLowerCase();return '<article class="card '+(done?'done':'')+'" data-id="'+r.id+'" data-group="'+r.group+'" data-search="'+search+'"><span class="badge">'+(r.group==='classic'?'alaprecept':r.group==='advanced'?'haladó':'ingyenes frissítés')+'</span><div class="recipe">'+item(r.weapon)+'<span class="symbol">+</span>'+item(r.passive)+'<span class="symbol">=</span>'+item(r.result,true)+'</div><div class="details unlock-details"><span class="unlock-entry"><b>Alapfegyver elérhetővé tétele:</b> '+componentUnlock(r.weapon,'weapon')+'</span><span class="unlock-entry"><b>Fejlesztő tárgy elérhetővé tétele:</b> '+(r.passive==='Nincs passzív tárgy'?'Nem szükséges hozzá passzív tárgy.':unlockLines(r.passive,'passive'))+'</span><span class="unlock-entry"><b>Evolúciós feltétel:</b> '+evolutionRule(r)+'</span><span class="unlock-entry"><b>Kapcsolódó karakter:</b> '+r.starter+'</span></div><div class="card-actions"><a class="learn" href="'+W+slug(r.weapon)+'" target="_blank" rel="noreferrer">Részletek a wikiben ↗</a><button class="check" onclick="toggleDone(\''+r.id+'\')">'+(done?'Megvan ✓':'Megjelölés')+'</button></div></article>'}
function render(){const q=document.querySelector('#search').value.trim().toLowerCase(),f=document.querySelector('.chip.active').dataset.filter;let n=0;document.querySelector('#recipeGrid').innerHTML=recipes.map(card).join('');document.querySelectorAll('#recipeGrid .card').forEach(c=>{const ok=(!q||c.dataset.search.includes(q))&&(f==='all'||c.dataset.group===f);c.hidden=!ok;if(ok)n++});document.querySelector('#recipeCount').textContent=n+' recept';document.querySelector('#empty').classList.toggle('show',!n)}
function toggleDone(id){const k='vs-'+id;localStorage.setItem(k,localStorage.getItem(k)==='1'?'0':'1');render()}
document.querySelector('#dlc').insertAdjacentHTML('beforebegin','<section id="arcana" class="panel"><div class="section-head"><div><h2>Arcana-kódex</h2><p>A 22 alap Arcana hatása, feloldása és ideális szerepe.</p></div><span id="arcanaCount" class="count"></span></div><div class="tip"><strong>Hogyan működik?</strong> Szerezd meg a Randomazzót a Gallo Towerben. Normál pályán egy lapot induláskor, továbbiakat pedig az Arcana-ládákból választhatsz. A Darkasso később külön Darkanákat nyit meg.</div><div class="controls codex-controls"><input id="arcanaSearch" class="search" type="search" placeholder="Például: gyógyítás, kritikus vagy Gold Fever…"></div><div class="codex-filters"><button class="codex-filter arcana-filter active" data-arcana="all">Mind</button><button class="codex-filter arcana-filter" data-arcana="offense">Sebzés</button><button class="codex-filter arcana-filter" data-arcana="survival">Túlélés</button><button class="codex-filter arcana-filter" data-arcana="control">Kontroll</button><button class="codex-filter arcana-filter" data-arcana="economy">Fejlődés</button><button class="codex-filter arcana-filter" data-arcana="utility">Hasznosság</button></div><div id="arcanaGrid" class="arcana-grid"></div></section><section id="characters" class="panel"><div class="section-head"><div><h2>Karakterkódex</h2><p>Az alapjáték 34 normál karaktere. A titkos szereplők a Titkok fülön vannak.</p></div><span id="characterCount" class="count"></span></div><input id="characterSearch" class="search" type="search" placeholder="Keress karakterre, kezdőfegyverre vagy feloldásra…"><div id="characterGrid" class="character-grid"></div></section><section id="mechanics" class="panel"><div class="section-head"><div><h2>Mechanikák</h2><p>A játék fontos, de könnyen elnézhető szabályai röviden.</p></div></div><div id="mechanicsGrid" class="mechanics-grid"></div></section>');
function renderArcanas(){const q=document.querySelector('#arcanaSearch').value.trim().toLowerCase(),group=document.querySelector('.arcana-filter.active').dataset.arcana,found=arcanas.filter(a=>(group==='all'||a.group===group)&&(!q||(a.name+' '+a.effect+' '+a.unlock).toLowerCase().includes(q)));document.querySelector('#arcanaGrid').innerHTML=found.map(a=>'<article class="arcana-card"><a class="arcana-art" href="'+W+slug(a.name)+'" target="_blank" rel="noreferrer"><img loading="lazy" src="'+img(a.name)+'" alt="'+a.name+' kártya" onerror="fallback(this)"></a><div><span class="badge">'+({offense:'sebzés',survival:'túlélés',control:'kontroll',economy:'fejlődés',utility:'hasznosság',special:'különleges'}[a.group])+'</span><h3>'+a.name+'</h3><p>'+a.effect+'</p><small><b>Feloldás:</b> '+a.unlock+'</small><a class="learn" href="'+W+slug(a.name)+'" target="_blank" rel="noreferrer">Részletek a wikiben ↗</a></div></article>').join('')||'<div class="tip">Nincs ilyen Arcana.</div>';document.querySelector('#arcanaCount').textContent=found.length+' lap'}
document.querySelector('#arcanaSearch').oninput=renderArcanas;document.querySelectorAll('.arcana-filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.arcana-filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderArcanas()});
function renderCharacters(){const q=document.querySelector('#characterSearch').value.trim().toLowerCase(),found=characters.filter(c=>!q||(c.name+' '+c.weapon+' '+c.unlock+' '+c.power).toLowerCase().includes(q));document.querySelector('#characterGrid').innerHTML=found.map(c=>'<article class="character-card"><div class="character-portrait"><img loading="lazy" src="'+selectImg(c.name)+'" alt="'+c.name+'" onerror="fallback(this)"></div><div><span class="badge">'+(c.group==='classic'?'alapjáték':'ingyenes frissítés')+'</span><h3>'+c.name+'</h3><p class="character-weapon">⚔ '+c.weapon+'</p><p><b>Képesség:</b> '+c.power+'</p><p><b>Feloldás:</b> '+c.unlock+'</p><a class="learn" href="'+W+slug(c.name)+'" target="_blank" rel="noreferrer">Karakterlap a wikiben ↗</a></div></article>').join('')||'<div class="tip">Nincs ilyen karakter.</div>';document.querySelector('#characterCount').textContent=found.length+' karakter'}document.querySelector('#characterSearch').oninput=renderCharacters;
document.querySelector('#mechanicsGrid').innerHTML=mechanics.map(m=>'<details class="mechanic-card"><summary><span class="mechanic-icon">'+m[0]+'</span><span>'+m[1]+'</span><span class="mechanic-open">＋</span></summary><div><p>'+m[2]+'</p><a class="learn" href="'+W+slug(m[3])+'" target="_blank" rel="noreferrer">Bővebben a wikiben ↗</a></div></details>').join('');renderArcanas();renderCharacters();
document.querySelector('#clearDone').onclick=()=>{recipes.forEach(r=>localStorage.removeItem('vs-'+r.id));render()};document.querySelector('#search').oninput=render;document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');render()});
const panelParents={progress:'profile',maps:'profile',secrets:'profile',death:'profile',special:'recipes',arcana:'recipes',characters:'recipes',mechanics:'recipes',dlc:'recipes',how:'recipes'};
function openPanel(id,scroll=true){const panel=document.querySelector('#'+id);if(!panel)return;document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));panel.classList.add('active');const parent=panelParents[id]||id;document.querySelectorAll('.primary-nav button').forEach(x=>x.classList.toggle('active',x.dataset.tab===parent));if(scroll)window.scrollTo({top:Math.max(0,panel.offsetTop-14),behavior:'smooth'});}
document.querySelectorAll('.primary-nav button').forEach(b=>b.onclick=()=>openPanel(b.dataset.tab));
document.addEventListener('click',e=>{const trigger=e.target.closest('[data-open]');if(trigger)openPanel(trigger.dataset.open)});
document.querySelector('#specialGrid').innerHTML=specials.map(s=>'<article class="card"><span class="badge">'+s.type+'</span>'+(s.passive?'<div class="recipe">'+item(s.base.join(' + '))+'<span class="symbol">+</span>'+item(s.passive)+'<span class="symbol">=</span>'+item(s.result,true)+'</div>':'<div class="recipe multi">'+item(s.base.join(' + '))+'<span class="symbol">→</span>'+item(s.result,true)+'</div>')+'<div class="details unlock-details"><span class="unlock-entry"><b>Összetevők elérhetővé tétele:</b></span>'+s.base.map(x=>unlockLines(x)).join('')+(s.passive?unlockLines(s.passive):'')+'<span class="unlock-entry"><b>'+s.type+' feltétele:</b> '+s.note+'</span></div><div class="card-actions"><a class="learn" href="'+W+slug(s.result)+'" target="_blank" rel="noreferrer">Részletek a wikiben ↗</a></div></article>').join('');
document.querySelector('#mapList').innerHTML=maps.map(m=>'<article class="map"><div class="map-icon">'+m[0]+'</div><div><h3>'+m[1]+'</h3><p>'+m[3]+'</p></div><span class="kind">'+m[2]+'</span></article>').join('');
document.querySelector('#dlcGrid').innerHTML=dlcs.map(d=>'<article class="dlc"><span class="badge">'+d[1]+'</span><h3>'+d[0]+'</h3><p class="dlc-hook">'+d[3]+'</p><p class="dlc-recipes"><b>Jellegzetes receptek:</b> '+d[2]+'</p><a href="'+W+slug(d[0])+'" target="_blank" rel="noreferrer">A DLC oldala a wikiben ↗</a></article>').join('');render();

