const baseCardRenderer=card;
card=function(r){const active=getFavorites().includes(r.id);return baseCardRenderer(r).replace('<div class="card-actions">','<div class="card-actions"><button class="fav '+(active?'active':'')+'" onclick="toggleFavorite(\''+r.id+'\')" aria-label="Kedvenc">♥</button>')};
function getFavorites(){try{return JSON.parse(localStorage.getItem('vs-favorites')||'[]')}catch{return []}}
function toggleFavorite(id){const f=getFavorites(),i=f.indexOf(id);i>=0?f.splice(i,1):f.unshift(id);localStorage.setItem('vs-favorites',JSON.stringify(f));recordRecent(id);render()}
document.querySelector('#recipes .section-head').insertAdjacentHTML('afterend','<section id="recentSection" class="recent-section" hidden><div class="recent-title"><h3>Legutóbbi receptek</h3><span>Gyors visszaugrás játék közben</span></div><div id="recentRecipes" class="recent-recipes"></div></section>');
document.head.insertAdjacentHTML('beforeend','<style>.recent-section{margin:0 0 14px}.recent-title{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:8px}.recent-title h3{margin:0;font-size:16px}.recent-title span{color:var(--muted);font-size:10px}.recent-recipes{display:flex;gap:8px;overflow-x:auto;padding:1px 1px 7px;scroll-snap-type:x proximity}.recent-card{flex:0 0 158px;scroll-snap-align:start;display:grid;grid-template-columns:34px 1fr 34px;align-items:center;gap:5px;min-height:58px;padding:8px;border:1px solid var(--line);border-radius:14px;background:#21132e;color:var(--ink);text-align:left}.recent-card img{width:32px;height:32px;object-fit:contain;image-rendering:pixelated}.recent-card b{font-size:10px;line-height:1.2;overflow-wrap:anywhere}.recent-card .arrow{color:var(--gold);text-align:center;font-weight:900}.recent-card .recent-result{display:grid;justify-items:center;gap:2px}.recent-card .recent-result small{max-width:48px;color:#ffd677;font-size:8px;line-height:1.05;text-align:center}.compact .recent-section{display:none}</style>');
function recordRecent(id){let r=[];try{r=JSON.parse(localStorage.getItem('vs-recent')||'[]')}catch{}r=[id,...r.filter(x=>x!==id)].slice(0,6);localStorage.setItem('vs-recent',JSON.stringify(r));renderRecent()}
function renderRecent(){let ids=[];try{ids=JSON.parse(localStorage.getItem('vs-recent')||'[]')}catch{}const found=ids.map(id=>recipes.find(r=>r.id===id)).filter(Boolean),section=document.querySelector('#recentSection');section.hidden=!found.length;document.querySelector('#recentRecipes').innerHTML=found.map(r=>'<button class="recent-card" onclick="openRecent(\''+r.id+'\')" aria-label="'+r.weapon+' recept megnyitása"><img src="'+img(r.weapon)+'" alt="" onerror="fallback(this)"><span><b>'+r.weapon+'</b><span class="arrow"> → </span></span><span class="recent-result"><img src="'+img(r.result)+'" alt="" onerror="fallback(this)"><small>'+r.result+'</small></span></button>').join('')}
function openRecent(id){const r=recipes.find(x=>x.id===id);if(!r)return;document.querySelector('#search').value=r.weapon;document.querySelectorAll('.filters .chip').forEach(x=>x.classList.toggle('active',x.dataset.filter==='all'));render();document.querySelector('#recipeGrid .card[data-id="'+id+'"]')?.scrollIntoView({behavior:'smooth',block:'center'})}
const baseToggleDone=toggleDone;toggleDone=function(id){recordRecent(id);baseToggleDone(id)};
render=function(){const q=document.querySelector('#search').value.trim().toLowerCase(),f=document.querySelector('.chip.active').dataset.filter,favs=getFavorites();let n=0;document.querySelector('#recipeGrid').innerHTML=recipes.map(card).join('');document.querySelectorAll('#recipeGrid .card').forEach(c=>{const ok=(!q||c.dataset.search.includes(q))&&(f==='all'||(f==='favorites'?favs.includes(c.dataset.id):c.dataset.group===f));c.hidden=!ok;if(ok)n++});document.querySelector('#recipeCount').textContent=n+' recept';document.querySelector('#empty').classList.toggle('show',!n)};
function setupFinder(){const names=[...new Set(recipes.flatMap(r=>[r.weapon,...iconNames(r.passive),r.result]))].sort((a,b)=>a.localeCompare(b));const sel=document.querySelector('#reverseFinder');sel.innerHTML='<option value="">Válassz fegyvert vagy passzív tárgyat…</option>'+names.map(n=>'<option>'+n+'</option>').join('');sel.onchange=()=>{const v=sel.value,out=document.querySelector('#finderResults');if(!v){out.innerHTML='';return}const found=recipes.filter(r=>r.weapon===v||r.result===v||iconNames(r.passive).includes(v));if(found[0])recordRecent(found[0].id);out.innerHTML='<div class="finder-results">'+found.map(r=>'<div class="mini-recipe">'+item(r.weapon)+'<b>+</b>'+item(r.passive)+'<b>→</b>'+item(r.result,true)+'</div>').join('')+'</div>'}}

const allWeapons=[...new Set([...recipes.map(r=>r.weapon),...Object.keys(weaponUnlocks)])].sort((a,b)=>a.localeCompare(b));
const allPassives=[...new Set(recipes.flatMap(r=>iconNames(r.passive)))].sort((a,b)=>a.localeCompare(b));
const emptyRun=()=>({version:2,weapons:Array(6).fill(null).map(()=>({name:'',max:false})),passives:Array(6).fill('')});
function loadRun(){try{const old=JSON.parse(localStorage.getItem('vs-run')||'null');if(!old)return emptyRun();return{version:2,weapons:Array(6).fill(null).map((_,i)=>({name:old.weapons?.[i]?.name||'',max:!!old.weapons?.[i]?.max})),passives:Array(6).fill('').map((_,i)=>old.passives?.[i]||''),passiveMax:old.passiveMax||{},context:old.context||{}}}catch{return emptyRun()}}
let runState=loadRun(),pickerContext={type:'weapon',index:0},pickerItems=[],currentRecommendations=[];
function gearSlot(type,value,i){const isWeapon=type==='weapon',name=isWeapon?value.name:value;if(!name)return '<button class="gear-slot empty" onclick="openGearPicker(\''+type+'\','+i+')"><span class="slot-add"><strong>＋</strong><span>'+(isWeapon?'Fegyver':'Passzív')+' '+(i+1)+'</span></span></button>';return '<article class="gear-slot"><button class="gear-main" onclick="openGearPicker(\''+type+'\','+i+')"><img src="'+img(name)+'" alt="'+name+'" onerror="fallback(this)"><b>'+name+'</b></button><button class="gear-remove" onclick="removeRunItem(\''+type+'\','+i+')" aria-label="'+name+' eltávolítása">×</button>'+(isWeapon?'<button class="gear-max '+(value.max?'active':'')+'" onclick="setRunMax('+i+','+(!value.max)+')">'+(value.max?'✓ MAX':'MAX?')+'</button>':'')+'</article>'}
function openGearPicker(type,index){pickerContext={type,index};document.querySelector('#pickerTitle').textContent=type==='weapon'?'Válassz fegyvert':'Válassz passzív tárgyat';document.querySelector('#pickerSearch').value='';renderGearPicker();const dialog=document.querySelector('#gearPicker');dialog.showModal?dialog.showModal():dialog.setAttribute('open','')}
function renderGearPicker(){const source=pickerContext.type==='weapon'?allWeapons:allPassives,q=document.querySelector('#pickerSearch').value.trim().toLowerCase(),only=document.querySelector('#onlyUnlocked').checked,unlocked=new Set(getProfile().unlocked[pickerContext.type==='weapon'?'weapons':'passives']||[]),selected=new Set(pickerContext.type==='weapon'?runState.weapons.map(x=>x.name):runState.passives);pickerItems=source.filter(n=>(!q||n.toLowerCase().includes(q))&&(!only||unlocked.has(n)));document.querySelector('#pickerGrid').innerHTML=pickerItems.length?pickerItems.map((n,i)=>'<button class="picker-item '+(selected.has(n)?'selected ':'')+(profileHasAny()&&!unlocked.has(n)?'locked':'')+'" onclick="chooseGear('+i+')"><img src="'+img(n)+'" alt="" onerror="fallback(this)"><span>'+n+'</span>'+(selected.has(n)?'<i class="item-check">✓</i>':'')+'</button>').join(''):'<div class="tip" style="grid-column:1/-1">Nincs találat. Kapcsold ki a „csak feloldott” szűrőt, vagy jelölj tárgyakat a profilodban.</div>'}
function chooseGear(i){const name=pickerItems[i];if(!name)return;const {type,index}=pickerContext;if(type==='weapon'){const duplicate=runState.weapons.findIndex((x,n)=>x.name===name&&n!==index);if(duplicate>=0)runState.weapons[duplicate]={name:'',max:false};runState.weapons[index]={name,max:false}}else{const duplicate=runState.passives.findIndex((x,n)=>x===name&&n!==index);if(duplicate>=0)runState.passives[duplicate]='';runState.passives[index]=name}document.querySelector('#gearPicker').close?.();renderRun()}
function removeRunItem(type,i){if(type==='weapon')runState.weapons[i]={name:'',max:false};else runState.passives[i]='';renderRun()}
function setRunMax(i,value){runState.weapons[i].max=value;renderRun()}
function addRunItem(type,name){if(type==='weapon'){const slot=runState.weapons.findIndex(x=>!x.name);if(slot>=0)runState.weapons[slot]={name,max:false}}else{const slot=runState.passives.findIndex(x=>!x);if(slot>=0)runState.passives[slot]=name}renderRun()}
function calculateRecommendations(){const weapons=runState.weapons.filter(x=>x.name),weaponNames=new Set(weapons.map(x=>x.name)),passives=new Set(runState.passives.filter(Boolean)),result=[],seen=new Set();const push=x=>{const key=x.type+'|'+x.name+'|'+x.title;if(!seen.has(key)){seen.add(key);result.push(x)}};weapons.forEach(w=>recipes.filter(r=>r.weapon===w.name).forEach(r=>{const required=iconNames(r.passive),missing=required.filter(x=>!passives.has(x)),noPassive=r.passive.startsWith('Nincs');if(w.max&&(noPassive||!missing.length))push({rank:0,kind:'ready',type:'result',name:r.result,title:r.result+' elkészíthető',text:'Minden feltétel teljesült. A következő megfelelő láda evolválhatja.',action:''});else if(!missing.length)push({rank:1,kind:'next',type:'max',name:r.weapon,title:'Fejleszd MAX-ra: '+r.weapon,text:'A fejlesztő tárgy már nálad van; már csak a fegyver szintje hiányzik.',action:''});else missing.forEach(n=>push({rank:2,kind:'next',type:'passive',name:n,title:'Válaszd: '+n,text:'Ez kell a '+r.weapon+' → '+r.result+' evolúcióhoz.',action:'Hozzáadás'}))}));
specials.filter(s=>s.type==='Unió').forEach(s=>{const bases=s.base.flatMap(components),owned=bases.filter(x=>weaponNames.has(x)),missing=bases.filter(x=>!weaponNames.has(x));if(owned.length&&missing.length===1)push({rank:2,kind:'synergy',type:'weapon',name:missing[0],title:'Unióhoz: '+missing[0],text:'A '+s.result+' másik fegyver-összetevője már nálad van.',action:'Hozzáadás'});if(!missing.length){const notMax=bases.filter(n=>!weapons.find(w=>w.name===n)?.max),passiveMissing=s.passive?iconNames(s.passive).filter(x=>!passives.has(x)):[];if(!notMax.length&&!passiveMissing.length)push({rank:0,kind:'ready',type:'result',name:s.result,title:s.result+' unió kész',text:'Minden összetevő teljesült; nyiss ki egy megfelelő ládát.',action:''});else passiveMissing.forEach(n=>push({rank:2,kind:'next',type:'passive',name:n,title:'Az unióhoz kell: '+n,text:s.result+' elkészítéséhez szükséges.',action:'Hozzáadás'}))}});
if(weapons.length&&runState.passives.some(x=>!x)&&!passives.has('Empty Tome'))push({rank:4,kind:'synergy',type:'passive',name:'Empty Tome',title:'Erős általános választás',text:'A rövidebb Cooldown szinte minden fegyveredet gyorsítja.',action:'Hozzáadás'});
if(!weapons.length)return[];return result.sort((a,b)=>a.rank-b.rank).slice(0,6)}
function applyRecommendation(i){const r=currentRecommendations[i];if(r?.action)addRunItem(r.type,r.name)}
function renderRecommendations(){currentRecommendations=calculateRecommendations();const out=document.querySelector('#runRecommendations');if(!runState.weapons.some(x=>x.name)){out.innerHTML='<div class="tip"><strong>Kezdd egy fegyverrel:</strong> bökj az első üres fegyverhelyre. Ezután itt rögtön megjelennek a hozzá illő választások.</div>';return}out.innerHTML=currentRecommendations.length?currentRecommendations.map((r,i)=>'<article class="recommendation '+r.kind+'"><div class="recommendation-icon"><img src="'+img(r.name)+'" alt="" onerror="fallback(this)"></div><div><span class="recommendation-rank">'+(r.rank===0?'Készen áll':r.kind==='synergy'?'Erős kombináció':'Következő lépés')+'</span><h3>'+r.title+'</h3><p>'+r.text+'</p></div>'+(r.action?'<button class="recommendation-action" onclick="applyRecommendation('+i+')">＋ '+r.action+'</button>':'')+'</article>').join(''):'<div class="tip">A kiválasztott tárgyakhoz most nincs további alapjáték-recept. Próbálj másik fegyvert vagy nézd meg az Uniók lapot.</div>'}
function renderRun(){document.querySelector('#weaponSlots').innerHTML=runState.weapons.map((w,i)=>gearSlot('weapon',w,i)).join('');document.querySelector('#passiveSlots').innerHTML=runState.passives.map((p,i)=>gearSlot('passive',p,i)).join('');const selectedWeapons=runState.weapons.filter(w=>w.name),selectedPassives=runState.passives.filter(Boolean);document.querySelector('#weaponSlotCount').textContent=selectedWeapons.length+' / 6';document.querySelector('#passiveSlotCount').textContent=selectedPassives.length+' / 6';let rows=[];selectedWeapons.forEach(w=>recipes.filter(r=>r.weapon===w.name).forEach(r=>{const req=iconNames(r.passive),noPassive=r.passive.startsWith('Nincs'),missing=req.filter(x=>!selectedPassives.includes(x)),ready=w.max&&(noPassive||missing.length===0),need=[];if(!w.max)need.push('MAX fegyverszint');if(missing.length)need.push(missing.join(', '));rows.push('<article class="run-state '+(ready?'ready':'waiting')+'"><img src="'+img(r.result)+'" alt="" onerror="fallback(this)"><div><b>'+r.weapon+' → '+r.result+'</b><small>'+(ready?'✓ KÉSZ: már csak egy evolúcióra képes láda kell.':'Még hiányzik: '+need.join(' és '))+'</small></div></article>')}));document.querySelector('#runResults').innerHTML=rows.length?rows.join(''):'<div class="tip">A kiválasztott fegyverek evolúciós állapota itt jelenik meg.</div>';renderRecommendations();localStorage.setItem('vs-run',JSON.stringify(runState));renderHome()}
document.querySelector('#pickerSearch').oninput=renderGearPicker;document.querySelector('#onlyUnlocked').onchange=renderGearPicker;document.querySelector('#closePicker').onclick=()=>document.querySelector('#gearPicker').close?.();document.querySelector('#gearPicker').onclick=e=>{if(e.target===e.currentTarget)e.currentTarget.close?.()};document.querySelector('#resetRun').onclick=()=>{runState=emptyRun();renderRun()};

const mainStages=['Mad Forest','Inlaid Library','Dairy Plant','Gallo Tower','Cappella Magna'];
const profileCatalogs={
  weapons:{title:'Fegyverek',icon:'⚔',items:allWeapons},
  passives:{title:'Passzív tárgyak',icon:'✦',items:allPassives},
  characters:{title:'Karakterek',icon:'🧛',items:characters.map(x=>x.name)},
  arcanas:{title:'Arcanák',icon:'🃏',items:arcanas.map(x=>x.name)},
  relics:{title:'Ereklyék',icon:'🔮',items:relics.map(x=>x[0])},
  stages:{title:'Pályák',icon:'🗺',items:[...new Set([...mainStages,...maps.map(x=>x[1])])]},
  secrets:{title:'Titkok',icon:'👁',items:secretData.map(x=>x.name)}
};
const emptyProfile=()=>({version:1,unlocked:Object.fromEntries(Object.keys(profileCatalogs).map(k=>[k,[]]))});
function loadProfile(){let p=emptyProfile();try{const saved=JSON.parse(localStorage.getItem('hs-profile-v1')||'null');if(saved?.unlocked)Object.keys(profileCatalogs).forEach(k=>p.unlocked[k]=[...new Set((saved.unlocked[k]||[]).filter(x=>profileCatalogs[k].items.includes(x)))])}catch{}try{const road=JSON.parse(localStorage.getItem('vs-progress')||'[]');if(road.includes(0))p.unlocked.stages.push('Cappella Magna');if(road.includes(2))p.unlocked.stages.push('Moongolow');if(road.includes(3))p.unlocked.relics.push('Yellow Sign');if(road.includes(5))p.unlocked.relics.push('Great Gospel');if(road.includes(6))p.unlocked.relics.push('Forbidden Scrolls of Morbane');if(road.includes(8))p.unlocked.relics.push("Gracia's Mirror",'Seventh Trumpet')}catch{}Object.keys(profileCatalogs).forEach(k=>p.unlocked[k]=[...new Set(p.unlocked[k])]);return p}
let profileState=loadProfile(),activeProfileCategory=localStorage.getItem('hs-profile-category')||'weapons',profileVisibleItems=[];
function getProfile(){return profileState}
function profileHasAny(){return Object.values(profileState.unlocked).some(a=>a.length)}
function saveProfile(){localStorage.setItem('hs-profile-v1',JSON.stringify(profileState))}
function profileItemImage(name,category){return category==='characters'?selectImg(name):img(name)}
function profileGoal(){const have=new Set(profileState.unlocked.relics),goals=[['Grim Grimoire','Szerezd meg a Grim Grimoire-t','Az Inlaid Library nyugati oldalán találod. A szünetmenüben megmutatja az evolúciós recepteket.'],['Milky Way Map','Keresd meg a Milky Way Mapet','A Dairy Plant déli részén található, és felfedi a pályatárgyakat a térképen.'],['Randomazzo','Nyisd meg az Arcana rendszert','Vedd fel a Randomazzót a Gallo Tower északi részén.'],["Sorceress' Tears",'Szerezd meg a Sorceress’ Tearst','A Gallo Tower déli részén találod; feloldja a Hurry módot.'],['Yellow Sign','A következő nagy lépés: Yellow Sign','Moongolow Lunar Eclipse eseménye után juss végig a Holy Forbidden folyosóján.'],['Great Gospel','Nyisd meg a Limit Breaket','Győzd le The Endert a Cappella Magnában, és vedd fel a Great Gospelt.'],['Forbidden Scrolls of Morbane','Indulhat a komoly titokvadászat','A Bone Zone-ban győzd le Sketamarit a Forbidden Scrolls megszerzéséhez.'],["Gracia's Mirror",'Nyisd meg az Inverse módot','Gyűjtsd össze az alap ereklyéket, majd látogasd meg az Eudaimonia Machine-t.'],['Seventh Trumpet','Nyisd meg az Endless módot','Térj vissza az Eudaimonia Machine-be a másik nagy ereklyéért.']];const next=goals.find(g=>!have.has(g[0]));if(next)return{title:next[1],text:next[2]};const missingWeapons=profileCatalogs.weapons.items.length-profileState.unlocked.weapons.length;if(missingWeapons)return{title:'Bővítsd a fegyvertárat',text:'Már minden fontos alap ereklye megvan. Még '+missingWeapons+' fegyver vár feloldásra.'};return{title:'A kódex mestere',text:'A fontos alap haladási célok teljesültek. Jöhetnek a titkok, kihívások és DLC-k!'}}
function renderHome(){const weapons=runState.weapons.filter(x=>x.name),passives=runState.passives.filter(Boolean),goal=profileGoal(),recommendation=calculateRecommendations()[0];document.querySelector('#homeRunSummary').textContent=weapons.length?(weapons.length+' fegyver · '+passives.length+' passzív'+(recommendation?' · '+recommendation.title:'')):'Válaszd ki az első fegyvert.';document.querySelector('#homeGoalTitle').textContent=goal.title;document.querySelector('#homeGoalSummary').textContent=goal.text}
function renderProfile(){const categories=Object.entries(profileCatalogs),total=categories.reduce((n,[,c])=>n+c.items.length,0),done=categories.reduce((n,[k])=>n+profileState.unlocked[k].length,0),percent=Math.round(done/total*100),goal=profileGoal();document.querySelector('#profilePercent').textContent=percent+'%';document.querySelector('#profileRing').style.setProperty('--profile-angle',(percent*3.6)+'deg');document.querySelector('#profileNext').innerHTML='<span class="next-label">Ajánlott következő cél</span><h3>'+goal.title+'</h3><p>'+goal.text+'</p>';document.querySelector('#profileCategories').innerHTML=categories.map(([k,c])=>{const n=profileState.unlocked[k].length,p=Math.round(n/c.items.length*100);return '<button class="profile-category '+(activeProfileCategory===k?'active':'')+'" onclick="setProfileCategory(\''+k+'\')"><b>'+c.icon+' '+c.title+'</b><span>'+n+' / '+c.items.length+'</span><div class="category-bar"><i style="width:'+p+'%"></i></div></button>'}).join('');renderProfileGrid();saveProfile();renderHome()}
function renderProfileGrid(){const cat=profileCatalogs[activeProfileCategory],q=document.querySelector('#profileSearch').value.trim().toLowerCase(),done=new Set(profileState.unlocked[activeProfileCategory]);profileVisibleItems=cat.items.filter(n=>!q||n.toLowerCase().includes(q));document.querySelector('#profileCategoryTitle').textContent=cat.icon+' '+cat.title;document.querySelector('#profileGrid').innerHTML=profileVisibleItems.length?profileVisibleItems.map((n,i)=>'<button class="profile-item '+(done.has(n)?'done':'')+'" onclick="toggleProfileItem('+i+')"><img loading="lazy" src="'+profileItemImage(n,activeProfileCategory)+'" alt="" onerror="fallback(this)"><span>'+n+'</span>'+(done.has(n)?'<i class="item-check">✓</i>':'')+'</button>').join(''):'<div class="tip" style="grid-column:1/-1">Nincs találat.</div>'}
function setProfileCategory(category){activeProfileCategory=category;localStorage.setItem('hs-profile-category',category);document.querySelector('#profileSearch').value='';renderProfile()}
function toggleProfileItem(i){const name=profileVisibleItems[i],list=profileState.unlocked[activeProfileCategory],at=list.indexOf(name);at>=0?list.splice(at,1):list.push(name);renderProfile()}
function markProfileDefaults(){const defaults={weapons:['Whip','Magic Wand','Knife','Axe','King Bible','Santa Water','Laurel'],passives:['Spinach','Armor'],characters:['Antonio Belpaese','Imelda Belpaese','Pasqualina Belpaese','Gennaro Belpaese'],stages:['Mad Forest']};Object.entries(defaults).forEach(([k,names])=>names.forEach(n=>{if(profileCatalogs[k].items.includes(n)&&!profileState.unlocked[k].includes(n))profileState.unlocked[k].push(n)}));renderProfile()}
function exportProfile(){const blob=new Blob([JSON.stringify(profileState,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pocket-grimoire-profile.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function importProfile(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result);if(!parsed?.unlocked)throw Error();const next=emptyProfile();Object.keys(profileCatalogs).forEach(k=>next.unlocked[k]=[...new Set((parsed.unlocked[k]||[]).filter(n=>profileCatalogs[k].items.includes(n)))]);profileState=next;renderProfile()}catch{alert('Ez nem érvényes Pocket Grimoire-profil.')}};reader.readAsText(file)}
document.querySelector('#profileSearch').oninput=renderProfileGrid;document.querySelector('#profileActionsToggle').onclick=()=>{const el=document.querySelector('#profileActions');el.hidden=!el.hidden};document.querySelector('#profileDefaults').onclick=markProfileDefaults;document.querySelector('#profileExport').onclick=exportProfile;document.querySelector('#profileImportButton').onclick=()=>document.querySelector('#profileImport').click();document.querySelector('#profileImport').onchange=e=>importProfile(e.target.files[0]);document.querySelector('#profileClear').onclick=()=>{if(confirm('Biztosan törlöd a teljes feloldási profilodat?')){profileState=emptyProfile();renderProfile()}};
function renderProgress(){const done=JSON.parse(localStorage.getItem('vs-progress')||'[]');document.querySelector('#progressRoadmap').innerHTML=progressSteps.map((s,i)=>'<article class="road-step '+(done.includes(i)?'done':'')+'"><button class="road-check" onclick="toggleProgress('+i+')">'+(done.includes(i)?'✓':i+1)+'</button><div><h3>'+s.title+'</h3><p>'+s.short+'</p><details><summary>Mutasd a részleteket</summary>'+s.detail+'</details></div></article>').join('');document.querySelector('#progressCount').textContent=done.length+'/'+progressSteps.length+' kész'}function toggleProgress(i){let d=JSON.parse(localStorage.getItem('vs-progress')||'[]');d=d.includes(i)?d.filter(x=>x!==i):[...d,i];localStorage.setItem('vs-progress',JSON.stringify(d));renderProgress()}
document.querySelector('#stageGuide').innerHTML=stageDetails.map(s=>'<article class="stage-card"><h3>'+s.name+'</h3><p class="items"><b>Földi tárgyak:</b> '+s.items+'</p><p><b>Ereklye:</b> '+s.relic+'</p><p><b>Koporsó:</b> '+s.coffin+'</p><p>'+s.tip+'</p></article>').join('');document.querySelector('#relicGuide').innerHTML=relics.map(r=>'<article class="relic-card"><h3>✦ '+r[0]+'</h3><p><b>'+r[1]+'</b></p><p>'+r[2]+'</p></article>').join('');
const relicGuide=document.querySelector('#relicGuide');document.querySelector('#stageGuide').insertAdjacentHTML('afterend','<div class="section-head relic-heading"><div><h2>Fontos ereklyék</h2><p>Ezek a fejlődési út részei, ezért átkerültek ide a felfedhető titkok közül.</p></div></div>');document.querySelector('.relic-heading').insertAdjacentElement('afterend',relicGuide);document.querySelector('#secretGrid').insertAdjacentHTML('beforebegin','<div class="tip secret-intro"><strong>Itt már minden kártya valódi titok:</strong> először csak egy homályos tippet látsz, a pontos megoldást pedig külön fedheted fel.</div>');
function renderSecrets(){const done=JSON.parse(localStorage.getItem('vs-secrets')||'[]');document.querySelector('#secretGrid').innerHTML=secretData.map((s,i)=>'<article class="secret-card '+(done.includes(i)?'done':'')+'"><header><h3>'+s.name+'</h3><button class="secret-done" onclick="toggleSecret('+i+')">'+(done.includes(i)?'✓ Megvan':'Megjelölés')+'</button></header><p>„'+s.hint+'”</p><details><summary>Megoldás felfedése</summary>'+s.solution+'</details></article>').join('');document.querySelector('#secretCount').textContent=done.length+'/'+secretData.length+' felfedezve'}function toggleSecret(i){let d=JSON.parse(localStorage.getItem('vs-secrets')||'[]');d=d.includes(i)?d.filter(x=>x!==i):[...d,i];localStorage.setItem('vs-secrets',JSON.stringify(d));renderSecrets()}
document.querySelector('#deathGuide').innerHTML='<div class="death-build"><h3>Ajánlott magbuild</h3><p><b>Clock Lancet + MAX Silver Ring + MAX Gold Ring → Infinite Corridor</b><br><b>Laurel + MAX Metaglio Left + MAX Metaglio Right → Crimson Shroud</b></p><p>Hasznos mellé: Empty Tome, Tirajisú, Armor és nagy sebzésű evolúciók. A két kulcsevolúcióhoz két külön láda kell.</p></div>'+[['Yellow Sign','Nyisd meg a Moongolowt négy Hyper alap pályával. Nem titkos karakterrel győzd le a különleges főellenfelet, juss a Holy Forbiddenre, és vedd fel a Yellow Signt.'],['Vedd fel mind a hat kulcstárgyat','Egy normál pályán vedd fel a Clock Lancetet és Laurelt, majd a térképen megjelenő két gyűrűt és két Metagliót. A tárgyőrök erősek, ezért ne rohanj mindegyikhez túl korán.'],['Fejlessz maximumra mindent','Clock Lancet 7; Laurel 7; Silver Ring 9; Gold Ring 9; Metaglio Left 9; Metaglio Right 9. A gyűrűk növelik a Curse-t, ezért a futam vége nehezebb lesz.'],['Nyiss ki két megfelelő ládát','Az elsőből készíts Infinite Corridort, a másodikból Crimson Shroudot. A Shroud legfeljebb 10-re korlátozza a bejövő sebzést; a Corridor megfelezi minden ellenség életerejét.'],['Éld túl a 30. percet','A Red Death 30:00-nál érkezik. Maradj mozgásban, hagyd, hogy a Corridor megfagyassza, a Shroud pedig megvédjen és visszaüssön.'],['Várd meg a White Handet','A Reaper öt Golden Egget dob, feloldja a Mask of the Red Death karaktert, majd a White Hand lezárja a futamot. Őt nem lehet legyőzni — ez a siker animációja.']].map((s,i)=>'<article class="death-step"><div class="death-num">'+(i+1)+'</div><div><h3>'+s[0]+'</h3><p>'+s[1]+'</p></div></article>').join('')+'<div class="tip"><strong>Miért működik?</strong> A Crimson Shroud önmagában is képes megölni a Reapert, de lassan. Az Infinite Corridor felezi az életerejét, ezért együtt gyorsak és biztonságosak. A régi Clerici + Runetracer saroktrükk ma már nem ajánlott.</div>';
function renderDlcs(){let owned;try{owned=JSON.parse(localStorage.getItem('vs-dlcs')||'null')}catch{}if(!owned)owned=dlcs.map(d=>d[0]);document.querySelector('#dlcSettings').innerHTML=dlcs.map((d,i)=>'<button class="dlc-toggle '+(owned.includes(d[0])?'active':'')+'" onclick="toggleDlc('+i+')">'+(owned.includes(d[0])?'✓ ':'')+d[0]+'</button>').join('');document.querySelector('#dlcGrid').innerHTML=dlcs.filter(d=>owned.includes(d[0])).map(d=>'<article class="dlc"><span class="badge">'+d[1]+'</span><h3>'+d[0]+'</h3><p class="dlc-hook">'+d[3]+'</p><p class="dlc-recipes"><b>Jellegzetes receptek:</b> '+d[2]+'</p><a href="'+W+slug(d[0])+'" target="_blank" rel="noreferrer">A DLC oldala a wikiben ↗</a></article>').join('')||'<div class="tip">Nincs kiválasztott DLC.</div>'}function toggleDlc(i){const name=dlcs[i][0];let d=JSON.parse(localStorage.getItem('vs-dlcs')||'null')||dlcs.map(x=>x[0]);d=d.includes(name)?d.filter(x=>x!==name):[...d,name];localStorage.setItem('vs-dlcs',JSON.stringify(d));renderDlcs()}
const challengeCharacters=['Antonio','Imelda','Poe','Pugnala','Poppea','Giovanna','Concetta','Christine','Zi’Assunta','Gyorunton'];function newChallenge(){const pick=a=>a[Math.floor(Math.random()*a.length)],c=pick(challengeCharacters),m=pick(maps),r=pick(recipes),twist=pick(['legfeljebb 4 fegyverrel','Armor nélkül','legalább 20% Curse mellett','Revival nélkül','a pálya egyik földi passzív tárgyával']);document.querySelector('#challengeBox').innerHTML='<h3>Mai küldetésed</h3><b>'+c+'</b> karakterrel menj a <b>'+m[1]+'</b> pályára, készíts <b>'+r.result+'</b> evolúciót, és teljesítsd <b>'+twist+'</b>.<br><button class="check" onclick="newChallenge()" style="margin-top:10px">Másikat kérek 🎲</button>';document.querySelector('#challengeBox').hidden=false}document.querySelector('#challengeToggle').onclick=newChallenge;
const compactButton=document.querySelector('#compactToggle');function setCompact(on){document.documentElement.classList.toggle('compact',on);compactButton.classList.toggle('active',on);compactButton.textContent=on?'⚡ Normál nézet':'⚡ Kompakt mód';localStorage.setItem('vs-compact',on?'1':'0')}compactButton.onclick=()=>setCompact(!document.documentElement.classList.contains('compact'));setCompact(localStorage.getItem('vs-compact')==='1');
let wakeLock=null;document.querySelector('#wakeToggle').onclick=async function(){if(!('wakeLock' in navigator)){this.textContent='☀ Nem támogatott';return}try{if(wakeLock){await wakeLock.release();wakeLock=null;this.classList.remove('active');this.textContent='☀ Kijelző ébren'}else{wakeLock=await navigator.wakeLock.request('screen');this.classList.add('active');this.textContent='☀ Ébren tartva'}}catch{this.textContent='☀ Engedélyezd Safariban'}};
// Small original pixel emblems for the interface; game artwork stays untouched.
